	    Advertiser entity = new Advertiser();
            entity.setAdvertiserId( event.getAdvertiserId() );
            entity.setName( event.getName() );
            entity.setLegalName( event.getLegalName() );
            entity.setIndustry( event.getIndustry() );
            entity.setWebsite( event.getWebsite() );
	    
    	// ------------------------------------------
