    /**
     * Method to retrieve the Advertiser via an AdvertiserPrimaryKey.
     * @param 	id Long
     * @return 	Advertiser
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Advertiser handle( FindAdvertiserQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getAdvertiserId() );
    }
    
    /**
     * Method to retrieve a collection of all Advertisers
     *
     * @param	query	FindAllAdvertiserQuery 
     * @return 	List<Advertiser> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Advertiser> handle( FindAllAdvertiserQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindAdvertiser,
 * but only if the id matches
 *
 * @param		entity	Advertiser
 */
	protected void emitFindAdvertiser( Advertiser entity ) {
		LOGGER.info("handling emitFindAdvertiser" );
		
	    queryUpdateEmitter.emit(FindAdvertiserQuery.class,
	                            query -> query.getFilter().getAdvertiserId().equals(entity.getAdvertiserId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllAdvertiser
	 * 
	 * @param		entity	Advertiser
	 */
	protected void emitFindAllAdvertiser( Advertiser entity ) {
		LOGGER.info("handling emitFindAllAdvertiser" );
		
	    queryUpdateEmitter.emit(FindAllAdvertiserQuery.class,
	                            query -> true,
	                            entity);
	}

